contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner) public payable {
        require(true);
        address before = c.owner();
        bool reverted;
        bool ok;
        ok = true;
        // decide the call outcome via try/catch, but make the state-changing call top-level
        if (before == address(this)) {
            try c.transferOwnership(newOwner) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.transferOwnership(newOwner) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }
        if (!reverted) { ok = (c.owner() == newOwner); }
        if (reverted) { ok = (c.owner() == before); }
        assert(ok && (reverted ? (c.owner() == before) : (c.owner() == newOwner)));
    }
    receive() external payable {}
}

